json get_view(AcDbDatabase *db,const json &p){
    need(db->tilemode(),"UNSUPPORTED_ON_PLATFORM","Camera tools currently require the modelspace tab");Transaction tx(db);auto view=tx.get<AcDbViewportTableRecord>(acdbGetCurVportTableRecordId(db));double f=output_factor(db,p);auto dir=view->viewDirection();auto center=view->centerPoint();auto result=identity(db);
    result["center"]=xyz(view->target(),f);result["direction"]=json::array({dir.x,dir.y,dir.z});result["height"]=view->height()*f;result["width"]=view->width()*f;result["viewCenter"]=json::array({center.x*f,center.y*f});result["twist"]=view->viewTwist();result["revision"]=state(db).revision;result["coordinateSystem"]="WCS";result["lengthUnit"]=p.value("lengthUnit",std::string("drawing_unit"));tx.commit();return result;
}
json set_view(AcDbDatabase *db,const json &p){
    auto &s=state(db);need(s.revision==number(p,"expectedRevision"),"STALE_REVISION");auto previous=get_view(db,p);const std::map<std::string,AcGeVector3d> directions={{"top",{0,0,1}},{"front",{0,-1,0}},{"right",{1,0,0}},{"isometric",{1,-1,1}}};auto direction=text(p,"direction");need(directions.contains(direction));double f=input_factor(db,p),height=annotation_number(p,"height")*f;need(height>0&&std::isfinite(height));double aspect=previous.at("width").get<double>()/previous.at("height").get<double>();need(std::isfinite(aspect)&&aspect>0&&std::isfinite(height*aspect));
    AcDbViewTableRecord view;view.setTarget(point(p,"center",f));view.setViewDirection(directions.at(direction));view.setHeight(height);view.setWidth(height*aspect);view.setCenterPoint({0,0});view.setViewTwist(0);view.setPerspectiveEnabled(false);check_cancel();s.writing=true;auto status=acedSetCurrentView(&view,nullptr);if(status==Acad::eOk)status=acedVports2VportTableRecords();s.writing=false;
    auto result=identity(db);result["operationId"]=text(p,"operationId");result["error"]=nullptr;result["applied"]=true;result["verified"]=false;result["status"]="succeeded";
    if(status!=Acad::eOk){result["status"]="unknown";result["applied"]=nullptr;result["error"]={{"code","TIMEOUT_UNKNOWN"},{"message","Native view update was rejected; inspect the camera before another write"},{"retryable",false}};return result;}
    s.revision++;cursors.clear();result["revision"]=s.revision;
    try{auto actual=get_view(db,p);result["view"]=actual;double tolerance=std::max(1.,annotation_number(p,"height"))*1e-7;need(annotation_close(actual.at("center"),p.at("center"),tolerance)&&std::abs(actual.at("height").get<double>()-annotation_number(p,"height"))<tolerance,"VERIFICATION_FAILED");auto a=actual.at("direction");auto dir=AcGeVector3d(a[0].get<double>(),a[1].get<double>(),a[2].get<double>()).normal();need((dir-directions.at(direction).normal()).length()<1e-7,"VERIFICATION_FAILED");result["verified"]=true;result["view"]=actual;}
    catch(...){result["status"]="failed";result["error"]={{"code","VERIFICATION_FAILED"},{"message","Updated native view could not be verified"},{"retryable",false}};}
    return result;
}
